{
  "name": "线性电机滑台",
  "name_en": "Linear Motor Rail",
  "manufacturer": "",
  "description": "用于实验平台上一维直线运动与定位的线性电机滑台。该设备支持通过网络连接、回零/参考点建立、设置负载与速度、执行绝对和相对位移、停止与恢复运动，并可读取当前位置、运动状态、回显信息及上次运动耗时，适合样品、机械臂末端或工装在导轨上的精密移动。",
  "description_en": "A linear motor rail for one-dimensional motion and positioning in laboratory setups. It supports network connection, homing/referencing, load and speed configuration, absolute and relative moves, stop and resume control, and reading current position, motion status, device echo, and last move time. It is suitable for precise transport of samples, fixtures, or robot-mounted payloads along a rail.",
  "actions": [
    {
      "action_name": "auto-read_intelligent",
      "description": "读取线性电机轴返回的回显信息。",
      "description_en": "Read the echo returned by the linear motor axis."
    },
    {
      "action_name": "auto-connect_rail",
      "description": "通过 Telnet 连接线性电机滑台，并检查或执行参考点/回零流程。",
      "description_en": "Connect to the linear motor rail via Telnet and check or perform referencing/homing."
    },
    {
      "action_name": "auto-set_ml",
      "description": "设置滑台运动时的负载质量参数。",
      "description_en": "Set the mass load parameter for rail motion."
    },
    {
      "action_name": "auto-set_vel",
      "description": "设置滑台的运动速度。",
      "description_en": "Set the motion speed of the rail."
    },
    {
      "action_name": "auto-check_move",
      "description": "阻塞等待，直到滑台到达指定位置。",
      "description_en": "Block until the rail reaches the specified position."
    },
    {
      "action_name": "auto-getProcessTime",
      "description": "获取上一次运动所用时间。",
      "description_en": "Get the time used for the last movement."
    },
    {
      "action_name": "auto-getPosition",
      "description": "获取线性电机滑台的当前位置。",
      "description_en": "Get the current position of the linear motor rail."
    },
    {
      "action_name": "auto-getStatus",
      "description": "获取线性电机轴的当前运动状态。",
      "description_en": "Get the current motion status of the linear motor axis."
    },
    {
      "action_name": "auto-move",
      "description": "将滑台移动到指定绝对位置。",
      "description_en": "Move the rail to a specified absolute position."
    },
    {
      "action_name": "auto-rel_move",
      "description": "按给定相对位移移动滑台。",
      "description_en": "Move the rail by a specified relative displacement."
    },
    {
      "action_name": "auto-stopMotion",
      "description": "停止滑台运动。",
      "description_en": "Stop the rail motion."
    },
    {
      "action_name": "auto-resumeMotion",
      "description": "恢复滑台运动。",
      "description_en": "Resume the rail motion."
    },
    {
      "action_name": "auto-disconnect_rail",
      "description": "断开与线性电机滑台的连接，可在断开前执行回零。",
      "description_en": "Disconnect from the linear motor rail, optionally homing before disconnection."
    },
    {
      "action_name": "auto-removeerror",
      "description": "清除线性电机轴的错误状态。",
      "description_en": "Clear the error state of the linear motor axis."
    }
  ],
  "tag_hints": [
    "linear motion",
    "motorized rail",
    "linear motor axis",
    "absolute positioning",
    "relative move",
    "homing",
    "telnet control",
    "motion status monitoring"
  ]
}

